const text = $input.first().json.output[0].content[0].text;
const clean = text.replace(/```json|```/g, '').trim();
const allBugs = JSON.parse(clean);

// Deduplicate by title
const seen = new Set();
const uniqueBugs = allBugs.filter(bug => {
  if (seen.has(bug.title)) return false;
  seen.add(bug.title);
  return true;
});

// Clean \n from all text fields
const cleanText = (str) => str ? str.replace(/\\n|\n/g, ' ').trim() : str;

// Capitalize first letter
const capitalize = (str) => str ? str.charAt(0).toUpperCase() + str.slice(1) : str;

const highBugs = uniqueBugs.filter(bug => 
  bug.severity.toLowerCase().includes('high')
);

// Truncate helper
const trim = (str, max = 120) =>
  str.length > max ? str.slice(0, max).trimEnd() + '…' : str;

const formatted = highBugs.map((bug, i) =>
  `#${i + 1} ${bug.title} [${bug.category}]\n` +
  `Issue: ${trim(cleanText(bug.description))}\n` +
  `Fix: ${trim(cleanText(bug.recommendation))}`
).join('\n\n');

const severityEmoji = (s) => {
  const val = s.toLowerCase().trim();
  if (val.includes('high')) return '🔴 High';
  if (val.includes('medium')) return '🟡 Medium';
  if (val.includes('low')) return '🟢 Low';
  return s;
};

return uniqueBugs.map(bug => ({
  json: {
    title: capitalize(cleanText(bug.title)),
    category: capitalize(cleanText(bug.category)),
    severity: severityEmoji(cleanText(bug.severity)),
    description: capitalize(trim(cleanText(bug.description))),
    recommendation: capitalize(trim(cleanText(bug.recommendation))),
    count: highBugs.length,
    emailBody: formatted || 'No high severity issues found.'
  }
}));
